[InitializeOnLoad]public static class Road824Straight{static Road824Straight(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("Road824Straight.request"))return;try{File.Delete("Road824Straight.request");}catch(IOException){return;}Run();}static void Run(){try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var f=root.GetComponentsInChildren<MeshFilter>(true).Single(v=>v.name=="polySurface824");var m=UnityEngine.Object.Instantiate(f.sharedMesh);var marks=new List<Vector4>();m.GetUVs(3,marks);if(marks.Count!=m.vertexCount)throw new Exception("Missing marking UVs");int old=Mathf.FloorToInt(marks[0].x/32);for(int i=0;i<marks.Count;i++){var v=marks[i];v.x-=Mathf.Floor(v.x/32)*32;v.z=-824;marks[i]=v;}m.SetUVs(3,marks);var site=new List<Vector4>();m.GetUVs(4,site);if(site.Count==m.vertexCount){for(int i=0;i<site.Count;i++)if(site[i].w<0)site[i]=Vector4.zero;m.SetUVs(4,site);}m.name="polySurface824 straight arrows";string path="Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/Meshes/824 Straight Arrows.asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing)AssetDatabase.DeleteAsset(path);AssetDatabase.CreateAsset(m,path);var prefab=PrefabUtility.LoadPrefabContents("Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");string transformPath=AnimationUtility.CalculateTransformPath(f.transform,root.transform);prefab.transform.Find(transformPath).GetComponent<MeshFilter>().sharedMesh=m;PrefabUtility.SaveAsPrefabAsset(prefab,"Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");PrefabUtility.UnloadPrefabContents(prefab);f.sharedMesh=m;PrefabUtility.RecordPrefabInstancePropertyModifications(f);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var center=f.GetComponent<Renderer>().bounds.center;typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,center+Vector3.up*32,center,"polySurface824-Straight-Arrows"});File.WriteAllText("FinalEnvironmentRoadReview/Road824StraightReport.txt","SUCCESS polySurface824 marking tile "+old+" -> straight arrows only; ONLY/turn arrows removed; speed markings suppressed only for this mesh; original geometry/base UV retained; scene and road prefab saved; shader errors="+ShaderUtil.GetShaderMessages(f.GetComponent<Renderer>().sharedMaterial.shader).Count(v=>v.severity.ToString()=="Error"));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/Road824StraightReport.txt","FAILED "+e);Debug.LogException(e);}}}
